class SessionStore extends ChangeNotifier{SessionStore({FlutterSecureStorage?storage}):_storage=storage??const FlutterSecureStorage();final FlutterSecureStorage _storage;String?accessToken,refreshToken;bool forcePasswordChange=false;Set<String>permissions={};String? get tenantId {try{final part=accessToken?.split('.')[1];if(part==null)return null;return (jsonDecode(utf8.decode(base64Url.decode(base64Url.normalize(part))))as Map<String,dynamic>)['tenantId']?.toString();}catch(_){return null;}}bool get authenticated=>accessToken!=null;bool hasPermission(String permission)=>permissions.contains(permission);bool get isTenantAdmin=>hasPermission('merchants.view')||hasPermission('branches.view')||hasPermission('users.view');Future<void>restore()async{try{accessToken=await _storage.read(key:'access_token');refreshToken=await _storage.read(key:'refresh_token');forcePasswordChange=(await _storage.read(key:'force_password_change'))=='true';if(accessToken!=null)_decode();}catch(_){accessToken=null;refreshToken=null;forcePasswordChange=false;permissions={};try{await _storage.delete(key:'access_token');await _storage.delete(key:'refresh_token');await _storage.delete(key:'force_password_change');}catch(_){}}notifyListeners();}Future<void>save(Map<String,dynamic>body)async{accessToken=body['accessToken']as String;refreshToken=body['refreshToken']as String?;if(body.containsKey('forcePasswordChange'))forcePasswordChange=body['forcePasswordChange']==true;await _storage.write(key:'access_token',value:accessToken);await _storage.write(key:'force_password_change',value:'$forcePasswordChange');if(refreshToken!=null)await _storage.write(key:'refresh_token',value:refreshToken);_decode();notifyListeners();}Future<void>clear()async{accessToken=null;refreshToken=null;forcePasswordChange=false;permissions={};await _storage.delete(key:'access_token');await _storage.delete(key:'refresh_token');await _storage.delete(key:'force_password_change');notifyListeners();}void _decode(){try{final part=accessToken!.split('.')[1],data=jsonDecode(utf8.decode(base64Url.decode(base64Url.normalize(part))))as Map<String,dynamic>;permissions=Set<String>.from((data['permissions'] as List?) ?? []);}catch(_){permissions={};}}}
